<?php require __DIR__.'/config/bootstrap.php';if(current_user())redirect('index.php');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$e=trim($_POST['email']);$st=db()->prepare("SELECT * FROM users WHERE email=? AND status='active'");$st->execute([$e]);$u=$st->fetch();if($u&&password_verify($_POST['password'],$u['password_hash'])){login_user($u);redirect($u['role']==='user'?'index.php':'admin/dashboard.php');}flash('error','Invalid login.');}$title='Login';require __DIR__.'/includes/header.php';?><h1>Login</h1><form class="form" method="post"><?=csrf_field()?><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button>Login</button></form><?php require __DIR__.'/includes/footer.php';?>